parseResponse = async (response: Response): Promise<unknown> => {
  const text = await response.text();

  if (!text) {
    return null;
  }

  try {
    return JSON.parse(text);
  } catch {
    return text;
  }
}

assertSuccessfulResponse = async (
  name: string,
  response: Response
): Promise<unknown> => {
  const body = await parseResponse(response);

  if (!response.ok) {
    throw new Error(
      `${name} failed with HTTP ${response.status}: ${JSON.stringify(body)}`
    );
  }

  console.log(`✅ ${name}: HTTP ${response.status}`);

  return body;
}

