    await db
      .update(aiActionProposals)
      .set({ status: 'EXPIRED' })
      .where(
        and(
          eq(aiActionProposals.id, proposal.id),
          eq(aiActionProposals.status, 'PENDING')
        )
      );
    throw AppError.gone('This proposal has expired. Ask Pulse to prepare a new one.');
