    })
    .where(
      and(
        eq(workspaceInvites.tokenHash, tokenHash),
        eq(workspaceInvites.status, 'PENDING'),
        lte(workspaceInvites.expiresAt, checkedAt)
      )
    )
    .returning({
      id: workspaceInvites.id,
    });

  return expiredInvite !== undefined;
}

