requireTrustedOrigin = (
  req: Request,
  res: Response,
  next: NextFunction
): void => {
  if (SAFE_METHODS.has(req.method)) {
    next();
    return;
  }

  const requestOrigin = getRequestOrigin(req);

  if (requestOrigin.status === 'invalid') {
    sendOriginError(res, 'Request origin could not be verified');

    return;
  }

  if (requestOrigin.status === 'missing') {
    if (env.NODE_ENV !== 'production') {
      next();
      return;
    }

    sendOriginError(res, 'Request origin could not be verified');

enforceApiEnvelope = (
  _req: Request,
  res: Response,
  next: NextFunction
): void => {
  const sendJson = res.json.bind(res);

  res.json = ((body: LegacyPayload) => {
    if (body && typeof body === 'object' && 'data' in body) {
      return sendJson({ data: body.data });
    }
    if (body?.success === true) return sendJson({ data: null });
    if (body?.success === false || body?.code) {
      return sendJson({
        error: {
          code: body.code ?? 'INTERNAL_ERROR',
          message: body.message ?? 'Request failed',
          fields: Object.fromEntries(
            (body.errors ?? []).map(({ field, message }) => [field, message])
          ),
        },
      });
    }
    return sendJson(body);
  }) as Response['json'];

